local WheelbarrowMaker = {}
local PRODUCTS = {
    simple_wood_wheelbarrow = { name = "Preprost lesen voziček", woodCost = 4, ironCost = 1, time = 4, cost = 100, science = 15, happiness = 1, description = "Preprost lesen voziček za prevoz." },
    iron_reinforced_wheelbarrow = { name = "Železnookrepljen voziček", woodCost = 3, ironCost = 2, time = 6, cost = 260, science = 28, happiness = 1, prestige = 2, description = "Železnookrepljen voziček za trgovce." },
    silver_trimmed_wheelbarrow = { name = "Srebrnoobrobljeni voziček", woodCost = 3, ironCost = 2, silverCost = 1, time = 9, cost = 620, science = 42, happiness = 2, prestige = 6, description = "Srebrnoobrobljeni voziček za plemiče." },
    gold_trimmed_wheelbarrow = { name = "Zlatookrasni voziček", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, time = 13, cost = 1400, science = 56, happiness = 3, prestige = 14, description = "Zlatookrasni voziček za visoke plemiče." },
    jewel_set_wheelbarrow = { name = "Draguljasta voziček", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 17, cost = 3000, science = 72, happiness = 5, prestige = 27, description = "Voziček z draguljem za visoko plemstvo." },
    royal_grand_wheelbarrow = { name = "Kraljevski veliki voziček", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 6500, science = 90, happiness = 12, prestige = 58, description = "Veliki kraljevski voziček z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    wheelbarrow_workshop = { name = "Vozičkarska delavnica", cost = { gold = 260, wood = 160, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    cartwright_loft = { name = "Kolarska podstrešje", cost = { gold = 950, wood = 320, stone = 280, silver = 6, iron = 8 }, upkeep = 22, qualityBonus = 18 },
    master_cartwright_atelier = { name = "Mojstrski kolarski atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_cartwright_palace = { name = "Kraljevska kolarska palača", cost = { gold = 11500, wood = 600, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
WheelbarrowMaker.woodStock = 22; WheelbarrowMaker.ironStock = 12; WheelbarrowMaker.silverStock = 6; WheelbarrowMaker.goldStock = 6; WheelbarrowMaker.jewelStock = 4; WheelbarrowMaker.pearlStock = 4
WheelbarrowMaker.productStock = {}; WheelbarrowMaker.buildings = {}; WheelbarrowMaker.maker = nil; WheelbarrowMaker.activeMaking = {}; WheelbarrowMaker.totalProducts = 0; WheelbarrowMaker.dayTimer = 0
function WheelbarrowMaker.init() WheelbarrowMaker.woodStock=22; WheelbarrowMaker.ironStock=12; WheelbarrowMaker.silverStock=6; WheelbarrowMaker.goldStock=6; WheelbarrowMaker.jewelStock=4; WheelbarrowMaker.pearlStock=4; WheelbarrowMaker.productStock={}; WheelbarrowMaker.buildings={}; WheelbarrowMaker.maker=nil; WheelbarrowMaker.activeMaking={}; WheelbarrowMaker.totalProducts=0; WheelbarrowMaker.dayTimer=0; print("[WheelbarrowMaker] Royal Wheelbarrow Maker System initialized (6 products, 4 buildings)") end
function WheelbarrowMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WheelbarrowMaker.maker={name=n or ("Vozičkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vozičkar najet: %s (spretnost: %d)",WheelbarrowMaker.maker.name,s),"success") end; return true end
function WheelbarrowMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WheelbarrowMaker.build(id) local ok,e=WheelbarrowMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WheelbarrowMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WheelbarrowMaker.getQualityBonus() local b=0; for _,bd in ipairs(WheelbarrowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WheelbarrowMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and WheelbarrowMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and WheelbarrowMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and WheelbarrowMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WheelbarrowMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WheelbarrowMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WheelbarrowMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WheelbarrowMaker.buildings==0 then return false,"Potrebna vozičkarska delavnica" end; if not WheelbarrowMaker.maker then return false,"Potreben vozičkar" end; return true end
function WheelbarrowMaker.make(pt,qty) qty=qty or 1; local ok,e=WheelbarrowMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then WheelbarrowMaker.woodStock=WheelbarrowMaker.woodStock-d.woodCost*qty end; if d.ironCost then WheelbarrowMaker.ironStock=WheelbarrowMaker.ironStock-d.ironCost*qty end; if d.silverCost then WheelbarrowMaker.silverStock=WheelbarrowMaker.silverStock-d.silverCost*qty end; if d.goldCost then WheelbarrowMaker.goldStock=WheelbarrowMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WheelbarrowMaker.jewelStock=WheelbarrowMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WheelbarrowMaker.pearlStock=WheelbarrowMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WheelbarrowMaker.maker then t=math.max(1,t-math.floor(WheelbarrowMaker.maker.skill/13)) end; table.insert(WheelbarrowMaker.activeMaking,{id="wheelbarrow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WheelbarrowMaker.completeMaking(m) local q=1.0+(WheelbarrowMaker.getQualityBonus()/100); if WheelbarrowMaker.maker then q=q+(WheelbarrowMaker.maker.skill/140) end; q=math.min(2.5,q); WheelbarrowMaker.productStock[m.productType]=(WheelbarrowMaker.productStock[m.productType] or 0)+m.quantity; WheelbarrowMaker.totalProducts=WheelbarrowMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WheelbarrowMaker.maker then WheelbarrowMaker.maker.itemsMade=WheelbarrowMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WheelbarrowMaker.maker.skill=math.min(100,WheelbarrowMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Voziček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"wheelbarrow.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function WheelbarrowMaker.update(dt) if not _G.state then return end; WheelbarrowMaker.dayTimer=WheelbarrowMaker.dayTimer+dt; if WheelbarrowMaker.dayTimer>=30 then WheelbarrowMaker.dayTimer=0; for i=#WheelbarrowMaker.activeMaking,1,-1 do local m=WheelbarrowMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WheelbarrowMaker.completeMaking(m); table.remove(WheelbarrowMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WheelbarrowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WheelbarrowMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WheelbarrowMaker.getStats() return {woodStock=WheelbarrowMaker.woodStock,ironStock=WheelbarrowMaker.ironStock,silverStock=WheelbarrowMaker.silverStock,goldStock=WheelbarrowMaker.goldStock,jewelStock=WheelbarrowMaker.jewelStock,pearlStock=WheelbarrowMaker.pearlStock,productStock=WheelbarrowMaker.productStock,numBuildings=#WheelbarrowMaker.buildings,hasMaker=WheelbarrowMaker.maker~=nil,makerName=WheelbarrowMaker.maker and WheelbarrowMaker.maker.name or "—",makerSkill=WheelbarrowMaker.maker and WheelbarrowMaker.maker.skill or 0,activeMaking=#WheelbarrowMaker.activeMaking,totalProducts=WheelbarrowMaker.totalProducts} end
return WheelbarrowMaker
